mapper.insert:

    SELECT SEQ_PLAYLISTS.NEXTVAL FROM DUAL

INSERT INTO PLAYLISTS (
PLAYLIST_ID, USER_ID, TITLE, DESCRIPTION,
COVER_IMAGE_URL, PUBLIC_YN, TAGS
) VALUES (
#{playlistId}, #{userId}, #{title}, #{description},
#{coverImageUrl}, #{publicYn}, #{tags,typeHandler=ListStringTypeHandler}
)

mapper.update:
UPDATE PLAYLISTS
SET PUBLIC_YN  = #{publicYn},
    UPDATED_AT = SYSTIMESTAMP
WHERE PLAYLIST_ID = #{playlistId}
  AND USER_ID = #{userId}

mapper.delete:
DELETE
FROM PLAYLISTS
WHERE PLAYLIST_ID = #{playlistId}
  AND USER_ID = #{userId}

mapper.select:
SELECT * FROM (SELECT * FROM PLAYLISTS WHERE PUBLIC_YN = 'Y'
ORDER BY VIEW_COUNT DESC
ORDER BY LIKE_COUNT DESC
) WHERE ROWNUM <= #{limit}
